"use client";

import { useRef, useEffect } from "react";
import { Camera, Paperclip, Send, User, Bot, Loader2, ArrowLeft } from "lucide-react";
import Link from "next/link";
import { useSearchParams } from "next/navigation";
import { useChat } from "@ai-sdk/react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import { motion, AnimatePresence } from "framer-motion";
import clsx from "clsx";
import { twMerge } from "tailwind-merge";

function cn(...inputs: (string | undefined | null | false)[]) {
  return twMerge(clsx(inputs));
}

export default function ChatPage() {
  const { messages, input, handleInputChange, handleSubmit, isLoading, setInput } = useChat({
    initialMessages: [
      {
        id: 'welcome-message',
        role: "assistant",
        content: "Hi there! I'm HelpNest, your IT support assistant. How can I help you today? Please explain your issue, paste an error message, or upload a screenshot."
      }
    ]
  });

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const searchParams = useSearchParams();
  const mode = searchParams.get("mode");

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  useEffect(() => {
    if (mode === "photo") {
      setInput("I have a photo of my issue. (Image upload feature is being implemented)");
    } else if (mode === "paste") {
      setInput("Here is my error message: \n\n```\n\n```");
    }
  }, [mode, setInput]);

  return (
    <div className="min-h-screen bg-slate-950 flex flex-col font-sans text-slate-100">
      {/* Header */}
      <motion.div 
        initial={{ y: -50, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        className="bg-slate-900/80 backdrop-blur-lg border-b border-white/10 p-4 flex items-center shadow-lg z-10 sticky top-0"
      >
        <Link href="/" className="mr-4 p-2 hover:bg-white/10 rounded-full transition-colors">
          <ArrowLeft className="h-5 w-5 text-slate-300" />
        </Link>
        <div>
          <h1 className="text-lg font-semibold tracking-tight text-white bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-indigo-400">
            HelpNest AI
          </h1>
          <p className="text-slate-400 text-xs mt-0.5">Powered by Gemini</p>
        </div>
      </motion.div>

      {/* Chat Area */}
      <div className="flex-1 max-w-4xl w-full mx-auto p-4 md:p-6 overflow-y-auto flex flex-col gap-6 pb-32">
        <AnimatePresence initial={false}>
          {messages.map((msg) => (
            <motion.div
              key={msg.id}
              initial={{ opacity: 0, y: 20, scale: 0.95 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              transition={{ duration: 0.3, ease: "easeOut" }}
              className={cn("flex gap-4", msg.role === "user" ? "flex-row-reverse" : "")}
            >
              <div className={cn(
                "flex-shrink-0 h-10 w-10 rounded-full flex items-center justify-center shadow-md",
                msg.role === "user" ? "bg-gradient-to-br from-blue-500 to-indigo-600" : "bg-gradient-to-br from-slate-700 to-slate-800 border border-slate-600"
              )}>
                {msg.role === "user" ? <User className="text-white h-5 w-5" /> : <Bot className="text-blue-300 h-5 w-5" />}
              </div>
              
              <div className={cn(
                "p-4 rounded-2xl max-w-[85%] shadow-sm overflow-hidden",
                msg.role === "user" 
                  ? "bg-blue-600/20 border border-blue-500/30 text-blue-50" 
                  : "bg-slate-800/50 backdrop-blur-sm border border-slate-700/50 text-slate-200"
              )}>
                <ReactMarkdown 
                  remarkPlugins={[remarkGfm]}
                  className="prose prose-invert prose-p:leading-relaxed prose-pre:bg-slate-900 prose-pre:border prose-pre:border-slate-700 max-w-none text-sm md:text-base"
                >
                  {msg.content}
                </ReactMarkdown>
              </div>
            </motion.div>
          ))}
        </AnimatePresence>
        
        {isLoading && messages[messages.length - 1]?.role === 'user' && (
           <motion.div
             initial={{ opacity: 0, y: 10 }}
             animate={{ opacity: 1, y: 0 }}
             className="flex gap-4"
           >
             <div className="flex-shrink-0 h-10 w-10 rounded-full flex items-center justify-center bg-gradient-to-br from-slate-700 to-slate-800 border border-slate-600 shadow-md">
               <Bot className="text-blue-300 h-5 w-5" />
             </div>
             <div className="p-4 rounded-2xl bg-slate-800/50 backdrop-blur-sm border border-slate-700/50 flex items-center gap-2">
               <div className="flex gap-1">
                 <motion.div className="h-2 w-2 bg-blue-400 rounded-full" animate={{ y: [0, -5, 0] }} transition={{ repeat: Infinity, duration: 0.6, delay: 0 }} />
                 <motion.div className="h-2 w-2 bg-blue-400 rounded-full" animate={{ y: [0, -5, 0] }} transition={{ repeat: Infinity, duration: 0.6, delay: 0.2 }} />
                 <motion.div className="h-2 w-2 bg-blue-400 rounded-full" animate={{ y: [0, -5, 0] }} transition={{ repeat: Infinity, duration: 0.6, delay: 0.4 }} />
               </div>
             </div>
           </motion.div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <motion.div 
        initial={{ y: 50, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        className="fixed bottom-0 left-0 right-0 bg-gradient-to-t from-slate-950 via-slate-950/90 to-transparent pt-10 pb-4 px-4"
      >
        <div className="max-w-4xl mx-auto">
          <form 
            onSubmit={handleSubmit} 
            className="bg-slate-900/80 backdrop-blur-md rounded-2xl shadow-xl border border-white/10 p-2 flex items-end gap-2 focus-within:border-blue-500/50 focus-within:ring-2 focus-within:ring-blue-500/20 transition-all"
          >
            <button type="button" className="p-3 text-slate-400 hover:text-blue-400 transition-colors rounded-xl hover:bg-white/5">
              <Camera className="h-5 w-5" />
            </button>
            <button type="button" className="p-3 text-slate-400 hover:text-blue-400 transition-colors rounded-xl hover:bg-white/5">
              <Paperclip className="h-5 w-5" />
            </button>
            <textarea
              value={input}
              onChange={handleInputChange}
              onKeyDown={(e) => {
                if (e.key === "Enter" && !e.shiftKey) {
                  e.preventDefault();
                  // @ts-ignore - this works in React
                  handleSubmit(e as any);
                }
              }}
              placeholder="Describe your issue or paste an error..."
              className="flex-1 bg-transparent p-3 outline-none resize-none max-h-32 text-slate-200 placeholder:text-slate-500"
              rows={1}
            />
            <button
              type="submit"
              disabled={isLoading || !input.trim()}
              className="p-3 bg-gradient-to-r from-blue-600 to-indigo-600 text-white rounded-xl hover:from-blue-500 hover:to-indigo-500 disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-md active:scale-95"
            >
              {isLoading ? <Loader2 className="h-5 w-5 animate-spin" /> : <Send className="h-5 w-5" />}
            </button>
          </form>
          <div className="text-center mt-3 text-xs text-slate-500">
            If this takes too long, you can always <Link href="/support" className="text-blue-400 hover:text-blue-300 hover:underline transition-colors">contact a real person</Link>.
          </div>
        </div>
      </motion.div>
    </div>
  );
}
